import{_ as a,a as t,c as n,ac as l}from"./chunks/framework.BSuaGltH.js";const p=JSON.parse('{"title":"第四册：流利英语 · Lesson 38 Water and the traveller","description":"学习 if、when 后的省略结构，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第四册：流利英语 · Lesson 38 Water and the traveller","description":"学习 if、when 后的省略结构，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第4册课时","summary":"学习 if、when 后的省略结构，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第四册：流利英语 · Lesson 37 The process of ageing","link":"/life/english/new-concept/book-4/unit-05/lesson-037"},"next":{"text":"第四册：流利英语 · Lesson 39 What every writer wants","link":"/life/english/new-concept/book-4/unit-05/lesson-039"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第四册：流利英语 · Lesson 37 The process of ageing","link":"/life/english/new-concept/book-4/unit-05/lesson-037"},"next":{"text":"第四册：流利英语 · Lesson 39 What every writer wants","link":"/life/english/new-concept/book-4/unit-05/lesson-039"}},"headers":[],"relativePath":"life/english/new-concept/book-4/unit-05/lesson-038.md","filePath":"life/english/new-concept/book-4/unit-05/lesson-038.md"}'),i={name:"life/english/new-concept/book-4/unit-05/lesson-038.md"};function r(o,e,s,h,d,c){return t(),n("div",null,[...e[0]||(e[0]=[l('<h1 id="第四册-流利英语-·-lesson-38-water-and-the-traveller" tabindex="-1">第四册：流利英语 · Lesson 38 Water and the traveller <a class="header-anchor" href="#第四册-流利英语-·-lesson-38-water-and-the-traveller" aria-label="Permalink to &quot;第四册：流利英语 · Lesson 38 Water and the traveller&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-4/contents">本册目录</a> · <a href="/life/english/new-concept/book-4/unit-05/overview">单元 5</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>围绕旅行中的饮水信息阅读实用性文字，注意地区、年代和具体条件决定说明能否适用。伴读训练如何核查来源、理解条件和表达未知，不复述旧文作为当前卫生处置指南。重点掌握省略条件从句，判断省略后是否仍能明确动作对象。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>source</td><td>/sɔːs/</td><td>n.</td><td>来源</td><td>a reliable source</td></tr><tr><td>container</td><td>/kənˈteɪnə/</td><td>n.</td><td>容器</td><td>a sealed container</td></tr><tr><td>guidance</td><td>/ˈɡaɪdəns/</td><td>n.</td><td>指导信息</td><td>current local guidance</td></tr><tr><td>uncertain</td><td>/ʌnˈsɜːtən/</td><td>adj.</td><td>不确定的</td><td>an uncertain source</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>when in doubt — 有疑问时</li><li>check with — 向某人或机构核实</li></ul><h2 id="语法讲解-if、when-后的省略结构" tabindex="-1">语法讲解：if、when 后的省略结构 <a class="header-anchor" href="#语法讲解-if、when-后的省略结构" aria-label="Permalink to &quot;语法讲解：if、when 后的省略结构&quot;">​</a></h2><p>if necessary、when available、if properly stored 等是条件或时间从句的压缩形式。if properly labelled 通常可展开为 if it is properly labelled，但被省略的主语必须能从主句或语境恢复。若前后主语不同，省略可能造成歧义。When travelling, check… 中 travelling 的执行者是祈使句隐含的 you；不能把同一短语接到 water is… 前，造成水在旅行的错误。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>When travelling, check current local guidance rather than rely on an old account.</p></blockquote><p>旅行时，应核查当前当地指导信息，而不是依赖一篇旧记述。</p><p>When travelling 相当于 when you are travelling；主句祈使句隐含主语 you，与分词执行者相同。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>When travelling, the water… 容易把 travelling 的执行者错接成 water；应明确人作主语。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>把 When travelling 与主句稍作停顿；朗读展开版本作对照，确认省略没有改变执行者。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>I could not confirm the source described in the old guide. When in doubt, I would check current local information. Any unresolved point should be clearly marked in our notes.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>为旅行笔记写三句信息核查提醒：提出未知、寻找当前来源、标记尚未确认事项。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>重点是信息核查而不是自创饮水处置步骤，省略条件句自然嵌入建议。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>展开示例中的 When travelling。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> When you are travelling</p><p><strong>解析：</strong> 补回主语 you 与 be。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>if necessary 通常是什么意思？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 如果有必要。</p><p><strong>解析：</strong> 省略形式相当于 if it is necessary。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>历史文章能否单独替代当前当地指导？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 不能。</p><p><strong>解析：</strong> 条件、设施和知识可能改变，示例要求核查当前信息。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：if、when 后的省略结构。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-4/unit-05/grammar">单元语法</a> · <a href="/life/english/new-concept/book-4/unit-05/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-4/unit-05/review">单元自测</a></p><p><a href="/life/english/new-concept/book-4/unit-05/lesson-037">上一课</a> · <a href="/life/english/new-concept/book-4/unit-05/overview">单元目录</a> · <a href="/life/english/new-concept/book-4/unit-05/lesson-039">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const b=a(i,[["render",r]]);export{p as __pageData,b as default};
